CREATE TABLE job_agent.application_handoff(id UUID PRIMARY KEY,application_package_id UUID NOT NULL REFERENCES job_agent.application_package(id) ON DELETE RESTRICT,application_package_revision_id UUID NOT NULL REFERENCES job_agent.application_package_revision(id) ON DELETE RESTRICT,job_posting_id UUID NOT NULL REFERENCES job_agent.job_posting(id) ON DELETE RESTRICT,review_decision_id UUID NOT NULL REFERENCES job_agent.application_review_decision(id) ON DELETE RESTRICT,apply_url_snapshot VARCHAR(2000) NOT NULL,apply_url_checksum CHAR(64) NOT NULL,source_job_checksum CHAR(64) NOT NULL,source_profile_checksum CHAR(64) NOT NULL,source_evaluation_checksum CHAR(64) NOT NULL,approved_artifact_manifest_checksum CHAR(64) NOT NULL,creation_idempotency_hash CHAR(64) NOT NULL UNIQUE,status VARCHAR(40) NOT NULL CHECK(status IN ('CREATED','READY_FOR_MANUAL_SUBMISSION','OPENED_EXTERNALLY','SUBMITTED_REPORTED_BY_USER','NOT_SUBMITTED','CANCELLED','BLOCKED','EXPIRED')),created_by VARCHAR(150) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,launched_at TIMESTAMPTZ,submission_reported_at TIMESTAMPTZ,record_version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_handoff_package_created ON job_agent.application_handoff(application_package_id,created_at DESC);
CREATE TABLE job_agent.application_submission_report(id UUID PRIMARY KEY,application_handoff_id UUID NOT NULL REFERENCES job_agent.application_handoff(id) ON DELETE RESTRICT,actor_id VARCHAR(150) NOT NULL,action VARCHAR(40) NOT NULL CHECK(action IN ('HANDOFF_CREATED','OPENED_EXTERNALLY','SUBMITTED_REPORTED_BY_USER','NOT_SUBMITTED','CANCELLED','BLOCKED','EXPIRED')),external_reference VARCHAR(200),note VARCHAR(1000),reported_submission_at TIMESTAMPTZ,idempotency_key_hash CHAR(64) UNIQUE,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_submission_report_handoff_created ON job_agent.application_submission_report(application_handoff_id,created_at);
